func newPortalSite() unsafe.Pointer { return unsafe.Pointer(new(extensionportal.PortalSite)) }

func newNPortalSite(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]extensionportal.PortalSite, n)))
}

func ptrPortalSite(p unsafe.Pointer, c int32) any {
	r := (*extensionportal.PortalSite)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Name
	case 4:
		return &r.Purpose
	case 5:
		return &r.Domains
	case 6:
		return &r.StartURL
	case 7:
		return &r.Credentials
	case 8:
		return &r.BrowserProfileID
	case 9:
		return &r.AllowActions
	case 10:
		return &r.Enabled
	case 11:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 12:
		return &r.Version
	case 13:
		return &r.CreatedAt
	case 14:
		return &r.UpdatedAt
	}
	return nil
}

func valuePortalSite(p unsafe.Pointer, c int32) any {
	r := (*extensionportal.PortalSite)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Name
	case 4:
		return r.Purpose
	case 5:
		if r.Domains == nil {
			return keel.EmptyJSONArray
		}
		return r.Domains
	case 6:
		return r.StartURL
	case 7:
		if r.Credentials == nil {
			return keel.EmptyJSONObject
		}
		return r.Credentials
	case 8:
		return r.BrowserProfileID
	case 9:
		return r.AllowActions
	case 10:
		return r.Enabled
	case 11:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 12:
		return r.Version
	case 13:
		return r.CreatedAt
	case 14:
		return r.UpdatedAt
	}
	return nil
}

